cards.solution:
def baca_perintah(baris):
    bagian = baris.strip().split(" ", 1)
    return bagian[0], (bagian[1] if len(bagian) > 1 else "")

def nomor_valid(teks, tugas):
    if not teks.isdigit() or not 1 <= int(teks) <= len(tugas):
        return None
    return int(teks) - 1

tugas = []
while True:
    perintah, sisa = baca_perintah(input())
    if perintah == "keluar":
        break
    if perintah == "tambah":
        tugas.append({"judul": sisa, "selesai": False})
    elif perintah == "lihat":
        if not tugas:
            print("Belum ada tugas")
        for no, t in enumerate(tugas, start=1):
            tanda = "x" if t["selesai"] else " "
            print(f"{no}. [{tanda}] {t['judul']}")
    elif perintah in ("selesai", "hapus"):
        i = nomor_valid(sisa, tugas)
        if i is None:
            print("Nomor tidak ada")
        elif perintah == "selesai":
            tugas[i]["selesai"] = True
        else:
            tugas.pop(i)
